"CM-2(2)": {"statement":[{"prose":"Maintain the currency, completeness, accuracy, and availability of the baseline configuration of the system using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated mechanisms that help organizations maintain consistent baseline configurations for systems include configuration management tools, hardware, software, firmware inventory tools, and network management tools. Automated tools can be used at the organization level, mission and business process level, or system level on workstations, servers, notebook computers, network components, or mobile devices. Tools can be used to track version numbers on operating systems, applications, types of software installed, and current patch levels. Automation support for accuracy and currency can be satisfied by the implementation of [CM-8(2)](#cm-8.2) for organizations that combine system component inventory and baseline configuration activities."],"params":[{"id":"CM-02(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms for maintaining baseline configuration of the system are defined"}],"related":["CM-7","IA-3","RA-5"],"objectives":[{"id":"cm-2.2_obj-1","label":"CM-02(02)[01]","prose":"the currency of the baseline configuration of the system is maintained using [Assignment: organization-defined automated mechanisms];"},{"id":"cm-2.2_obj-2","label":"CM-02(02)[02]","prose":"the completeness of the baseline configuration of the system is maintained using [Assignment: organization-defined automated mechanisms];"},{"id":"cm-2.2_obj-3","label":"CM-02(02)[03]","prose":"the accuracy of the baseline configuration of the system is maintained using [Assignment: organization-defined automated mechanisms];"},{"id":"cm-2.2_obj-4","label":"CM-02(02)[04]","prose":"the availability of the baseline configuration of the system is maintained using [Assignment: organization-defined automated mechanisms]."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing the baseline configuration of the system","configuration management plan","system design documentation","system architecture and configuration documentation","system configuration settings and associated documentation","system component inventory","configuration change control records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with configuration management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing baseline configurations","automated mechanisms implementing baseline configuration maintenance"]}],"references":[]},
"CM-2(3)": {"statement":[{"prose":"Retain [Assignment: organization-defined number] of previous versions of baseline configurations of the system to support rollback."}],"discussion":["Retaining previous versions of baseline configurations to support rollback include hardware, software, firmware, configuration files, configuration records, and associated documentation."],"params":[{"id":"CM-02(03)_ODP","kind":"Assignment","value":"[Assignment: organization-defined number]","guideline":"the number of previous baseline configuration versions to be retained is defined"}],"related":[],"objectives":[{"id":"cm-2.3_obj","label":"CM-02(03)","prose":"[Assignment: organization-defined number] of previous baseline configuration version(s) of the system is/are retained to support rollback."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing the baseline configuration of the system","configuration management plan","system architecture and configuration documentation","system configuration settings and associated documentation","copies of previous baseline configuration versions","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with configuration management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing baseline configurations"]}],"references":[]},
